export const EXPANDED_SCENES=groups.flatMap(([topic,category,items],group)=>items.map(([title,line,action],index)=>({id:`daily-v2-${group}-${index}`,topic,category,title,line,action})));
export const EXPANDED_STORIES=EXPANDED_SCENES.map(x=>[x.title,x.line,x.action,'학생의 이유를 듣고 다음 확인 시간 정하기',x.action+'를 함께 의논합니다. 학생이 바로 실천할지, 조금 기다릴지도 확인합니다.',x.title+'에 관해 필요한 방법과 다음 확인을 의논했다.']);
export function storyFor(state,p,topic,index){const bank=EXPANDED_SCENES.filter(s=>s.topic===topic||(topic==='feelings'&&s.topic==='friends')||(topic==='autonomy'&&s.topic==='roles'));const item=bank[index%bank.length];if(!item)return null;const level=p.relation>=65?'close':p.relation<45?'cautious':'comfortable';const opening={cautious:'선생님, 잠깐 여쭤봐도 돼요? '+item.line,comfortable:item.line,close:'선생님께 먼저 말씀드리고 싶었어요. '+item.line+' 제가 생각한 방법도 들어 주실래요?'}[level];const low=state.config.grade<3,high=state.config.grade>4;
 return {sceneId:item.id,opening:opening+(low?' 처음 한 번은 같이 확인해 주세요.':high?' 우리가 정할 수 있는 부분도 알고 싶어요.':''),choices:[['무엇이 가장 불편했는지 먼저 들려줄래?',item.action+'부터 같이 해 볼까?','지금은 기다렸다가 다시 이야기하고 싶니?'],['네가 고른 방법으로 작은 부분부터 해 보자.','다른 방법과 비교하고 네 의견을 다시 듣자.','약속한 때에 다시 확인하자.']],answers:[['제가 본 장면부터 말해 볼게요. '+item.line,level==='cautious'?'바로 하기는 망설여져요. 먼저 방법을 한 번 보여 주세요.':item.action+'를 해 보고 싶어요. 막히면 다시 물을게요.','지금은 잠깐 생각할래요. 다음 쉬는 시간에 다시 이야기할 수 있을까요?'],[item.action+' 중 제가 할 부분부터 골라 볼게요.','두 방법을 생각해 보니 아직 어려운 부분도 있어요. 그 부분부터 다시 여쭤볼게요.','기억해 둘게요. 해 본 다음에 잘된 점과 어려운 점을 말할게요.']]};
}
